import json

def process_batch(orders):
    revenue = 0.0
    failed_orders = []
    for order in orders:
        try:
            quantity = order['quantity']
            amount = order['amount']
            if isinstance(quantity, int) and isinstance(amount, (int, float)):
                revenue += amount * quantity
            else:
                failed_orders.append(order['id'])
        except (KeyError, TypeError):
            pass
    return revenue, failed_orders
